function validate([prices]) {
  if (!Array.isArray(prices) || prices.length < 1 || prices.length > 500) return 'prices needs 1 to 500 values.';
  if (prices.some(p => !Number.isInteger(p) || p < 1 || p > 1000)) return 'Each price is a whole number from 1 to 1000.';
  return null;
}

