function finalPrices(prices) {
  const answer = prices.slice();
  const stack = [];

  for (let i = 0; i < prices.length; i++) {
    while (stack.length > 0 && prices[stack[stack.length - 1]] >= prices[i]) {
      const top = stack.pop();
      answer[top] = prices[top] - prices[i];
    }
    stack.push(i);
  }
  return answer;
}

